/// The literal a column falls back to, if the model declares one.
pub fn column_default(table: &str, column: &str) -> Option<&'static str> {
    COLUMN_DEFAULTS
        .iter()
        .find(|(t, c, _)| *t == table && *c == column)
        .map(|(_, _, literal)| *literal)
}
